def parse_statement(text):
    months = {m: i for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], start=1)}

    def parse_date(s):
        s = s.strip()
        m = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", s)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
            if m:
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            else:
                m = re.fullmatch(r"(\d{1,2}) ([A-Za-z]{3}) (\d{4})", s)
                if not m or m.group(2) not in months:
                    return None
                d, mo, y = int(m.group(1)), months[m.group(2)], int(m.group(3))
        if not (1 <= mo <= 12 and 1 <= d <= 31):
            return None
        return f"{y:04d}-{mo:02d}-{d:02d}"

    def parse_amount(s):
        s = s.strip()
        negative = False
        if s.startswith("(") and s.endswith(")"):
            negative = True
            s = s[1:-1].strip()
        elif s.endswith(" DR"):
            negative = True
            s = s[:-3].strip()
        if s and s[0] in "₹$":
            s = s[1:].strip()
        s = s.replace(",", "")
        if not re.fullmatch(r"\d+(\.\d+)?", s):
            return None
        value = float(s)
        return -value if negative else value

    records = []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split(",")
        if len(parts) < 3:
            continue
        date = parse_date(parts[0])
        amount = parse_amount(parts[-1])
        description = ",".join(parts[1:-1]).strip()
        if date is None or amount is None or not description:
            continue
        records.append({"date": date, "description": description, "amount": amount})

    records.sort(key=lambda r: r["date"])
    return records

