class RateTree:
    def __init__(self, spec):
        self._nodes = {}
        root_count = 0
        for name, (capacity, refill_rate, parent) in spec.items():
            if parent is None:
                root_count += 1
            elif parent not in spec:
                raise ValueError(f"unknown parent {parent!r} for node {name!r}")
            self._nodes[name] = {
                "capacity": float(capacity),
                "rate": float(refill_rate),
                "parent": parent,
                "tokens": float(capacity),  # start FULL
                "last": 0.0,
            }
        if root_count != 1:
            raise ValueError("spec must contain exactly one root (parent None)")

    def _chain(self, name):
        chain = []
        node = self._nodes[name]
        chain.append((name, node))
        seen = {name}
        while node["parent"] is not None:
            pname = node["parent"]
            if pname in seen:
                raise ValueError("cycle detected in spec")
            seen.add(pname)
            node = self._nodes[pname]
            chain.append((pname, node))
        return chain

    @staticmethod
    def _refill(node, now):
        elapsed = now - node["last"]
        if elapsed > 0.0:
            node["tokens"] = min(node["capacity"],
                                 node["tokens"] + elapsed * node["rate"])
            node["last"] = now
        # if now <= last: no refill, keep last (never go backwards)

    def allow(self, name, n=1.0, now=0.0):
        if name not in self._nodes:
            raise KeyError(name)
        chain = self._chain(name)
        # Update every touched node's state to `now` first (per-node elapsed).
        for _, node in chain:
            self._refill(node, now)
        # Check all, then debit all or none.
        if all(node["tokens"] >= n for _, node in chain):
            for _, node in chain:
                node["tokens"] -= n
            return True
        return False

