    RATES = {"INR": 1, "USD": 83.5, "EUR": 90.25}
    DATE_FORMATS = ("%d/%m/%Y", "%Y-%m-%d", "%d %b %Y", "%b %d, %Y")

    def split_fields(line):
        """Split on top-level commas, honoring double-quoted fields with "" escapes.
        Returns a list of stripped field strings, or None on malformed quoting."""
        fields = []
        i, n = 0, len(line)
        while True:
            while i < n and line[i] in " \t":
                i += 1
            if i < n and line[i] == '"':
                i += 1
                buf = []
                closed = False
                while i < n:
                    if line[i] == '"':
                        if i + 1 < n and line[i + 1] == '"':
                            buf.append('"')
                            i += 2
                        else:
                            i += 1
                            closed = True
                            break
                    else:
                        buf.append(line[i])
                        i += 1
                if not closed:
                    return None
                while i < n and line[i] in " \t":
                    i += 1
                fields.append("".join(buf).strip())
                if i >= n:
                    return fields
                if line[i] != ",":
                    return None
                i += 1
            else:
                j = line.find(",", i)
                if j == -1:
                    fields.append(line[i:].strip())
                    return fields
                fields.append(line[i:j].strip())
                i = j + 1

    def parse_date(raw):
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(raw, fmt).strftime("%Y-%m-%d")
            except ValueError:
                pass
        return None

    def parse_amount(raw, currency):
        s = raw.strip()
        negative = False
        m = re.match(r"^\((.*)\)$", s)
        if m:
            negative = True
            s = m.group(1).strip()
        if s.endswith("DR") and (len(s) == 2 or s[-3] in " \t"):
            negative = True
            s = s[:-2].strip()
        if s[:1] in ("₹", "$", "€"):
            s = s[1:].strip()
        if not re.fullmatch(r"\d{1,3}(,\d{3})*(\.\d+)?|\d+(\.\d+)?", s):
            return None
        value = float(s.replace(",", ""))
        if negative:
            value = -value
        return round(value * RATES[currency], 2)

    results = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = split_fields(line)
        if fields is None:
            continue
        if len(fields) == 5:
            # "Mon D, YYYY" dates split on their internal comma; rejoin them.
            fields = [fields[0] + ", " + fields[1]] + fields[2:]
        if len(fields) != 4:
            continue
        raw_date, description, raw_amount, currency = fields
        if currency not in RATES:
            continue
        date = parse_date(raw_date)
        if date is None:
            continue
        amount_inr = parse_amount(raw_amount, currency)
        if amount_inr is None:
            continue
        key = (date, description, amount_inr)
        if key in seen:
            continue
        seen.add(key)
        results.append({"date": date, "description": description, "amount_inr": amount_inr})

    results.sort(key=lambda r: (r["date"], -abs(r["amount_inr"])))
    return results

def parse_ledger(text):
    import re
    from datetime import date as _date

    months = {m: i + 1 for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"])}
    rates = {"INR": 1, "USD": 83.5, "EUR": 90.25}

    def split_fields(line):
        fields, cur, in_quotes = [], [], False
        for ch in line:
            if ch == '"':
                in_quotes = not in_quotes
                cur.append(ch)
            elif ch == ',' and not in_quotes:
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        if in_quotes:
            return None
        fields.append(''.join(cur))
        return fields

    def unquote(field):
        s = field.strip()
        if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
            s = s[1:-1].replace('""', '"')
        return s.strip()

    def parse_date(s):
        s = s.strip()
        m = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        elif (m := re.fullmatch(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)):
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        elif (m := re.fullmatch(r'(\d{1,2}) ([A-Za-z]{3}) (\d{4})', s)) \
                and m.group(2) in months:
            d, mo, y = int(m.group(1)), months[m.group(2)], int(m.group(3))
        elif (m := re.fullmatch(r'([A-Za-z]{3}) (\d{1,2}),\s*(\d{4})', s)) \
                and m.group(1) in months:
            mo, d, y = months[m.group(1)], int(m.group(2)), int(m.group(3))
        else:
            return None
        try:
            return _date(y, mo, d).isoformat()
        except ValueError:
            return None

    def parse_amount(s, currency):
        s = s.strip()
        negative = False
        if s.endswith('DR'):
            s = s[:-2].strip()
            negative = True
        if s.startswith('(') and s.endswith(')'):
            s = s[1:-1].strip()
            negative = True
        if s[:1] in ('₹', '$', '€'):
            s = s[1:].strip()
        if not re.fullmatch(r'(\d{1,3}(,\d{3})*|\d+)(\.\d+)?', s):
            return None
        value = float(s.replace(',', ''))
        if negative:
            value = -value
        return round(value * rates[currency], 2)

    rows = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = split_fields(line)
        if fields is None:
            continue
        if len(fields) == 5:
            # "Mon D, YYYY" dates split across the first two fields
            fields = [fields[0] + ',' + fields[1]] + fields[2:]
        if len(fields) != 4:
            continue
        raw_date, raw_desc, raw_amt, raw_cur = fields
        currency = raw_cur.strip()
        if currency not in rates:
            continue
        iso_date = parse_date(raw_date)
        if iso_date is None:
            continue
        amount_inr = parse_amount(raw_amt, currency)
        if amount_inr is None:
            continue
        rows.append({"date": iso_date,
                     "description": unquote(raw_desc),
                     "amount_inr": amount_inr})

    seen = set()
    unique = []
    for r in rows:
        key = (r["date"], r["description"], r["amount_inr"])
        if key not in seen:
            seen.add(key)
            unique.append(r)

    return sorted(unique, key=lambda r: (r["date"], -abs(r["amount_inr"])))

import re
from datetime import date as _date


def parse_ledger(text):
    months = {m: i for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], 1)}
    mon = "|".join(months)
    date_patterns = [
        (re.compile(r"(\d{1,2})/(\d{1,2})/(\d{4})"),
         lambda g: (int(g[2]), int(g[1]), int(g[0]))),
        (re.compile(r"(\d{4})-(\d{2})-(\d{2})"),
         lambda g: (int(g[0]), int(g[1]), int(g[2]))),
        (re.compile(r"(\d{1,2})\s+(%s)\s+(\d{4})" % mon),
         lambda g: (int(g[2]), months[g[1]], int(g[0]))),
        (re.compile(r"(%s)\s+(\d{1,2}),\s*(\d{4})" % mon),
         lambda g: (int(g[2]), months[g[0]], int(g[1]))),
    ]
    rates = {"INR": 1.0, "USD": 83.5, "EUR": 90.25}

    def parse_date(line):
        for rx, conv in date_patterns:
            m = rx.match(line)
            if m:
                y, mo, d = conv(m.groups())
                try:
                    _date(y, mo, d)
                except ValueError:
                    return None
                return "%04d-%02d-%02d" % (y, mo, d), line[m.end():]
        return None

    def strip_symbol(s):
        return s[1:].lstrip() if s[:1] in "₹$€" else s

    def parse_amount(s):
        s = s.strip()
        neg = False
        if s.endswith("DR"):
            neg = True
            s = s[:-2].rstrip()
        s = strip_symbol(s)
        if s.startswith("(") and s.endswith(")"):
            neg = True
            s = s[1:-1].strip()
            s = strip_symbol(s)
        s = s.replace(",", "")
        if not re.fullmatch(r"\d+(\.\d+)?", s):
            return None
        value = float(s)
        return -value if neg else value

    def parse_line(line):
        parsed = parse_date(line)
        if parsed is None:
            return None
        iso, rest = parsed
        rest = rest.lstrip()
        if not rest.startswith(","):
            return None
        rest = rest[1:].lstrip()
        if rest.startswith('"'):
            buf = []
            i = 1
            closed = False
            while i < len(rest):
                ch = rest[i]
                if ch == '"':
                    if i + 1 < len(rest) and rest[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(ch)
                    i += 1
            if not closed:
                return None
            desc = "".join(buf).strip()
            tail = rest[i:].lstrip()
            if not tail.startswith(","):
                return None
            remainder = tail[1:]
        else:
            idx = rest.find(",")
            if idx == -1:
                return None
            desc = rest[:idx].strip()
            remainder = rest[idx + 1:]
        if "," not in remainder:
            return None
        amount_str, cur = remainder.rsplit(",", 1)
        cur = cur.strip()
        if cur not in rates:
            return None
        value = parse_amount(amount_str)
        if value is None:
            return None
        amount_inr = round(value * rates[cur], 2)
        return {"date": iso, "description": desc, "amount_inr": amount_inr}

    rows = []
    seen = set()
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        row = parse_line(line)
        if row is None:
            continue
        key = (row["date"], row["description"], row["amount_inr"])
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)

    rows.sort(key=lambda r: (r["date"], -abs(r["amount_inr"])))
    return rows

