    RATES = {"INR": 1, "USD": 83.5, "EUR": 90.25}
    SYMBOLS = ("₹", "$", "€")
    DATE_FORMATS = ("%d/%m/%Y", "%Y-%m-%d", "%d %b %Y", "%b %d, %Y")

    def split_fields(line):
        fields, cur, in_q = [], [], False
        i, n = 0, len(line)
        while i < n:
            ch = line[i]
            if in_q:
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        cur.append('""')
                        i += 2
                        continue
                    in_q = False
                cur.append(ch)
            elif ch == '"' and not "".join(cur).strip():
                in_q = True
                cur.append(ch)
            elif ch == ",":
                fields.append("".join(cur))
                cur = []
            else:
                cur.append(ch)
            i += 1
        if in_q:
            return None
        fields.append("".join(cur))
        return fields

    def parse_date(raw):
        s = " ".join(raw.split())
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
            except ValueError:
                pass
        return None

    def parse_desc(raw):
        s = raw.strip()
        if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
            s = s[1:-1].replace('""', '"')
        return s.strip()

    def parse_amount(raw, currency):
        s = raw.strip()
        neg = False
        for sym in SYMBOLS:
            if s.startswith(sym):
                s = s[len(sym):].strip()
                break
        if s.startswith("(") and s.endswith(")") and len(s) >= 2:
            neg = True
            s = s[1:-1].strip()
        stripped = re.sub(r"\s+DR$", "", s)
        if stripped != s:
            neg = True
            s = stripped.strip()
        for sym in SYMBOLS:
            if s.startswith(sym):
                s = s[len(sym):].strip()
                break
        if "," in s:
            if not re.fullmatch(r"\d{1,3}(,\d{3})+(\.\d+)?", s):
                return None
            s = s.replace(",", "")
        if not re.fullmatch(r"\d+(\.\d+)?", s):
            return None
        value = float(s) * RATES[currency]
        if neg:
            value = -value
        return round(value, 2)

    rows = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = split_fields(line)
        if fields is None:
            continue
        if len(fields) == 5:
            f0, f1 = fields[0].strip(), fields[1].strip()
            if re.fullmatch(r"[A-Za-z]{3}\s+\d{1,2}", f0) and re.fullmatch(r"\d{4}", f1):
                fields = [f0 + ", " + f1] + fields[2:]
        if len(fields) != 4:
            continue
        date = parse_date(fields[0])
        if date is None:
            continue
        currency = fields[3].strip()
        if currency not in RATES:
            continue
        amount_inr = parse_amount(fields[2], currency)
        if amount_inr is None:
            continue
        rows.append({"date": date, "description": parse_desc(fields[1]),
                     "amount_inr": amount_inr})

    seen = set()
    unique = []
    for row in rows:
        key = (row["date"], row["description"], row["amount_inr"])
        if key not in seen:
            seen.add(key)
            unique.append(row)

    unique.sort(key=lambda r: (r["date"], -abs(r["amount_inr"])))
    return unique

class LRUCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}     # key -> (value, stored_time)
        self._order = []    # least-recently-used first

    def _expired(self, key, now):
        return now - self._data[key][1] > self.ttl

    def _purge(self, now):
        for k in list(self._order):
            if k in self._data and self._expired(k, now):
                del self._data[k]
                self._order.remove(k)

    def put(self, key, value, now):
        if key in self._data:
            self._data[key] = (value, now)
            self._order.remove(key)
            self._order.append(key)
            return
        if len(self._data) >= self.capacity:
            self._purge(now)
        if len(self._data) >= self.capacity:
            victim = self._order.pop(0)
            del self._data[victim]
        self._data[key] = (value, now)
        self._order.append(key)

    def get(self, key, now):
        if key not in self._data:
            return None
        if self._expired(key, now):
            return None
        self._order.remove(key)
        self._order.append(key)
        return self._data[key][0]

    def size(self, now):
        return sum(1 for k in self._data if not self._expired(k, now))

