def max_load(events):
    if not events:
        return (0, 0)

    # Sweep line: +weight at start, -weight at end.
    # Because spans are half-open [start, end), an event ending at t and
    # another starting at t never overlap, so at each distinct time we apply
    # all deltas (both -w and +w) before sampling the load.
    deltas = {}
    for start, end, weight in events:
        deltas[start] = deltas.get(start, 0) + weight
        deltas[end] = deltas.get(end, 0) - weight

    peak = 0
    peak_t = 0
    load = 0
    first = True
    for t in sorted(deltas):
        load += deltas[t]
        if first or load > peak:
            peak = load
            peak_t = t
            first = False
    return (peak, peak_t)

def max_load(events):
    if not events:
        return (0, 0)
    deltas = []
    for start, end, weight in events:
        deltas.append((start, weight))
        deltas.append((end, -weight))
    deltas.sort()
    peak = 0
    peak_t = 0
    load = 0
    i = 0
    n = len(deltas)
    while i < n:
        t = deltas[i][0]
        while i < n and deltas[i][0] == t:
            load += deltas[i][1]
            i += 1
        if load > peak:
            peak = load
            peak_t = t
    return (peak, peak_t)

from collections import defaultdict


def max_load(events):
    if not events:
        return (0, 0)
    delta = defaultdict(int)
    for start, end, weight in events:
        delta[start] += weight
        delta[end] -= weight
    load = 0
    peak = 0
    peak_t = 0
    first = True
    for t in sorted(delta):
        load += delta[t]
        if first or load > peak:
            peak = load
            peak_t = t
            first = False
    return (peak, peak_t)

def max_load(events):
    if not events:
        return (0, 0)
    deltas = []
    for start, end, weight in events:
        deltas.append((start, weight))
        deltas.append((end, -weight))
    # Sort by time; at equal times apply removals (-w) before additions (+w)
    # so a closing [a,b) and an opening [b,c) never overlap at t == b.
    deltas.sort()
    peak = 0
    peak_t = 0
    load = 0
    i = 0
    n = len(deltas)
    while i < n:
        t = deltas[i][0]
        while i < n and deltas[i][0] == t:
            load += deltas[i][1]
            i += 1
        if load > peak:
            peak = load
            peak_t = t
    return (peak, peak_t)

from datetime import datetime
from zoneinfo import ZoneInfo


def elapsed_seconds(tz_name, start, end):
    tz = ZoneInfo(tz_name)

    def to_instant(s):
        # fold=0 (the default) gives exactly the required semantics under
        # zoneinfo/PEP 495: a skipped (spring-forward) reading is interpreted
        # with the pre-transition UTC offset, and an ambiguous (fall-back)
        # reading resolves to the first, pre-transition occurrence.
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=tz, fold=0)
        return dt.timestamp()

    return to_instant(end) - to_instant(start)

import unicodedata


def truncate_graphemes(s, n):
    clusters = []
    join_next = False  # a ZWJ forces the next code point into the current cluster
    for ch in s:
        if ch == "‍":
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = True
        elif unicodedata.category(ch) == "Mn":
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = False
        else:
            if join_next and clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = False
    if len(clusters) <= n:
        return s
    return "".join(clusters[:n]) + "..."

