def truncate_graphemes(s, n):
    clusters = []
    pending_join = False  # a ZWJ has forced the next code point to join the current cluster
    for ch in s:
        if pending_join:
            # Forced by a preceding ZWJ to join the current cluster.
            clusters[-1] += ch
