            # and forces the next code point to join as well.
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            pending_join = True
        elif unicodedata.category(ch) == "Mn":
            # Combining mark attaches to the cluster it follows,
            # or forms its own cluster at the very start of the string.
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
        else:
            clusters.append(ch)
    if len(clusters) <= n:
        return s
    return "".join(clusters[:n]) + "..."

